/**
 * TypeScript mirror of the serde JSON emitted by the acad-rust WASM section
 * entry points (`dwg_meta` / `dwg_section_json` / `dwg_entity_page` /
 * `dwg_block_entity_page` in `rust/src/lib.rs`).
 *
 * These shapes are NOT invented: every field here is transcribed from a real
 * fixture generated by the offline native dumper (`rust/src/bin/dump_fixture.rs`
 * -> `__tests__/fixtures/sample-drawing/*.json`) against acadrust 0.6.3, and the
 * `acadrust-model.schema.spec.ts` snapshot test re-asserts that contract so an
 * upstream 0.6.x serde-schema drift fails loudly instead of silently producing a
 * half-mapped database.
 *
 * Serde tag conventions observed in the fixtures (do not "tidy" these — they are
 * deliberate and per-enum):
 *   * `Handle(u64)`          -> a plain JSON `number`.
 *   * `DxfVersion`           -> a PascalCase variant-name string (e.g. "AC1024").
 *   * `Color`                -> externally-tagged, default PascalCase:
 *                              `"ByLayer"` / `"ByBlock"` / `"None"` (unit
 *                              variants as bare strings) or `{"Index":n}` /
 *                              `{"Rgb":{"r":..,"g":..,"b":..}}` (newtype/struct).
 *   * `LineWeight`           -> same convention: `"Default"` / `"ByLayer"` /
 *                              `"ByBlock"` / `"NoLineweight"` or `{"Value":n}`.
 *   * `Transparency`         -> the ONE exception: it is
 *                              `#[serde(rename_all = "snake_case")]`, so
 *                              `"by_layer"` / `"by_block"` (lower case) or
 *                              `{"explicit":n}`.
 *   * `EntityType`           -> externally-tagged single-key object whose key is
 *                              the variant name (e.g. `{"Line":{...}}`), with a
 *                              nested `Dimension` -> `{"Linear":{...}}` second
 *                              level. Fully modeling every variant is a later
 *                              milestone; Slice 0 only needs the shared
 *                              `common` block, typed here.
 *   * `Table<T>`             -> `{ handle: number; entries: Record<string, T> }`
 *                              (the record key is the entry name).
 */

/**
 * Section discriminators accepted by `dwg_section_json`, kept byte-for-byte in
 * sync with `SECTION_KINDS` in `rust/src/lib.rs` (the dumper's `debug_assert!`
 * and the worker's runtime guard both rely on this list matching Rust).
 */
export const ACADRUST_SECTION_KINDS = [
  'header',
  'summary-info',
  'classes',
  'tables-layer',
  'tables-ltype',
  'tables-style',
  'tables-blockrecord',
  'tables-dimstyle',
  'tables-appid',
  'tables-view',
  'tables-vport',
  'tables-ucs',
  'tables-vx',
  'objects'
] as const

export type AcadRustSectionKind = (typeof ACADRUST_SECTION_KINDS)[number]

/** `dwg_meta` output: bounded summary used for progress + pagination upper bounds. */
export interface AcadRustMeta {
  version: string
  dwgSourceVersion: string
  entityCount: number
  modelSpaceEntityCount: number
  blockRecordCount: number
  layerCount: number
  lineTypeCount: number
  textStyleCount: number
  dimStyleCount: number
  vportCount: number
  objectCount: number
  classCount: number
}

/** Shared 3D / 2D point shapes (serde emits plain `x`/`y`/`z` numbers). */
export interface AcadRustPoint3d {
  x: number
  y: number
  z: number
}

export interface AcadRustPoint2d {
  x: number
  y: number
}

/** `acadrust::types::color::Color` (externally tagged, PascalCase). */
export type AcadRustColor =
  | 'ByLayer'
  | 'ByBlock'
  | 'None'
  | { Index: number }
  | { Rgb: { r: number; g: number; b: number } }

/** `acadrust::types::line_weight::LineWeight` (externally tagged, PascalCase). */
export type AcadRustLineWeight =
  | 'Default'
  | 'ByLayer'
  | 'ByBlock'
  | 'NoLineweight'
  | { Value: number }

/**
 * `acadrust::types::transparency::Transparency` (snake_case tags — the
 * intentional exception to the PascalCase convention above).
 */
export type AcadRustTransparency =
  | 'by_layer'
  | 'by_block'
  | { explicit: number }

/** `Table<T>` wrapper: symbol-table control handle + name-keyed entries. */
export interface AcadRustTable<T> {
  handle: number
  entries: Record<string, T>
}

/** `LayerTableEntry.flags` (a plain struct of booleans, NOT bit-coded). */
export interface AcadRustLayerFlags {
  frozen: boolean
  locked: boolean
  frozen_in_new_viewport: boolean
  off: boolean
  xref_dependent: boolean
}

/** One LAYER table entry. */
export interface AcadRustLayer {
  handle: number
  name: string
  flags: AcadRustLayerFlags
  color: AcadRustColor
  color_name: string | null
  book_name: string | null
  line_type: string
  line_weight: AcadRustLineWeight
  plot_style: string
  is_plottable: boolean
  transparency: AcadRustTransparency
  description: string
  material: number
  plotstyle_handle: number
  xref_block_record_handle: number
}

/** `LineTypeSegment.complex` inner payload (dash-attached shape/text). */
export interface AcadRustLineTypeComplex {
  content: { Shape?: { shape_number: number }; Text?: unknown }
  style_handle: number
  scale: number
  rotation: number
  absolute_rotation: boolean
  offset: [number, number]
}

/** One dash/space element of a linetype pattern. */
export interface AcadRustLineTypeElement {
  length: number
  complex: AcadRustLineTypeComplex | null
}

/** One LTYPE table entry. */
export interface AcadRustLineType {
  handle: number
  name: string
  description: string
  elements: AcadRustLineTypeElement[]
  pattern_length: number
  alignment: string
  xref_dependent: boolean
  xref_block_record_handle: number
}

/** `TextStyleTableEntry.flags` (backward / upside_down booleans). */
export interface AcadRustTextStyleFlags {
  backward: boolean
  upside_down: boolean
}

/** One STYLE table entry. */
export interface AcadRustTextStyle {
  handle: number
  name: string
  flags: AcadRustTextStyleFlags
  height: number
  width_factor: number
  oblique_angle: number
  last_height: number
  font_file: string
  big_font_file: string
  true_type_font: string
  true_type_font_flags: number
  xref_dependent: boolean
  xref_block_record_handle: number
  is_shape_file: boolean
  is_vertical: boolean
  annotative: boolean
}

/**
 * One DIMSTYLE table entry (`acadrust` dimension-style table record). Field
 * names are the DXF parameter mnemonics verbatim. Wire-type notes the mapper
 * must respect:
 * - the DXF group-70-class switches (`dimse1`/`dimtol`/…) arrive as plain
 *   booleans, not the `0|1` numbers the data-model record attrs use;
 * - arrow blocks are dual: `dimblk*` hold legacy handle codes while
 *   `dimblk*_name` carry the resolved block name the record wants;
 * - `dimdsep` is the decimal-separator *character code* (46 = '.'), not the
 *   string the data-model stores;
 * - `dimclr*_true_color` supplements the ACI `dimclr*` when a truecolor is
 *   set (not yet mapped — the record attrs only carry ACI numbers).
 */
export interface AcadRustDimStyle {
  handle: number
  name: string
  xref_reference: boolean
  xref_resolved: boolean
  xref_dependent: boolean
  xref_handle: number
  dimclrd: number
  dimclrd_true_color: AcadRustColor | null
  dimdle: number
  dimdli: number
  dimgap: number
  dimlwd: number
  dimsd1: boolean
  dimsd2: boolean
  dimclre: number
  dimclre_true_color: AcadRustColor | null
  dimexe: number
  dimexo: number
  dimlwe: number
  dimse1: boolean
  dimse2: boolean
  dimfxl: number
  dimfxlon: boolean
  dimasz: number
  dimblk: number
  dimblk1: number
  dimblk2: number
  dimldrblk: number
  dimblk_name: string
  dimblk1_name: string
  dimblk2_name: string
  dimsah: boolean
  dimcen: number
  dimtsz: number
  dimclrt: number
  dimclrt_true_color: AcadRustColor | null
  dimtxt: number
  dimjust: number
  dimtad: number
  dimtvp: number
  dimtih: boolean
  dimtoh: boolean
  dimtix: boolean
  dimsoxd: boolean
  dimtfill: number
  dimtfillclr: number
  dimtfillclr_true_color: AcadRustColor | null
  dimtmove: number
  dimtxtdirection: boolean
  dimaltmzf: number
  dimaltmzs: string
  dimmzf: number
  dimmzs: string
  dimtxsty_handle: number
  dimtxsty: string
  dimscale: number
  dimlfac: number
  dimlunit: number
  dimdec: number
  dimrnd: number
  dimdsep: number
  dimzin: number
  dimaunit: number
  dimadec: number
  dimazin: number
  dimalt: boolean
  dimaltf: number
  dimaltd: number
  dimaltu: number
  dimalttd: number
  dimaltrnd: number
  dimapost: string
  dimaltz: number
  dimalttz: number
  dimtol: boolean
  dimlim: boolean
  dimtp: number
  dimtm: number
  dimtdec: number
  dimtfac: number
  dimtolj: number
  dimtzin: number
  dimatfit: number
  dimtofl: boolean
  dimupt: boolean
  dimfit: number
  dimpost: string
  dimfrac: number
  dimarcsym: number
  dimjogang: number
  dimltex_handle: number
  dimltex1_handle: number
  dimltex2_handle: number
  dimunit: number
  annotative: boolean
}

/**
 * HEADER variables subset actually consumed by the Slice 0 mapper. Field names
 * match the serde output verbatim; unrelated variables (dimension styling,
 * loft/camera/time fields, etc.) are intentionally omitted — `dwg_section_json`
 * returns them too, they are simply not modeled until a mapping needs them.
 */
export interface AcadRustHeader {
  angle_base: number
  angle_direction: number
  angular_unit_format: number
  angular_unit_precision: number
  linear_unit_format: number
  linear_unit_precision: number
  insertion_units: number
  measurement: number
  linetype_scale: number
  current_entity_linetype_scale: number
  current_entity_color: AcadRustColor
  current_line_weight: number
  lineweight_display: boolean
  paper_space_linetype_scaling: boolean
  show_model_space: boolean
  ortho_mode: boolean
  object_snap_mode: number
  point_display_mode: number
  point_display_size: number
  model_space_extents_min: AcadRustPoint3d
  model_space_extents_max: AcadRustPoint3d
  handle_seed: number
  current_layer_name: string
  current_text_style_name: string
  current_dimstyle_name: string
  current_linetype_name: string
  multiline_style: string
  current_mleader_style_name: string
}

/** Parsed wrapper types for the three Slice 0 tables. */
export type AcadRustLayerTable = AcadRustTable<AcadRustLayer>
export type AcadRustLineTypeTable = AcadRustTable<AcadRustLineType>
export type AcadRustTextStyleTable = AcadRustTable<AcadRustTextStyle>
/** DIMSTYLE table (`Table<DimStyleTableEntry>`, M4.6). */
export type AcadRustDimStyleTable = AcadRustTable<AcadRustDimStyle>

/**
 * A single VPORT table record (`tables-vport.json`, M4.7): the active model-space
 * viewport. Field names mirror the acadrust `entities::Vport` serde; camera fields
 * land in the data-model record's `gsView` and snap/grid/ucs in its attrs. The
 * display/flag fields (`standardFlag` bit-pack, `render_mode` enum, `grid_flags`,
 * `ambient_color`, and the background/visual-style/ucs handle cross-refs) are
 * carried here but NOT folded into the record — the Architecture-A DXF baseline
 * stores defaults for them (group 70 = 0), so mapping them would break parity.
 */
export interface AcadRustVport {
  handle: number
  name: string
  // Viewport rectangle (graphics-area fractions, DXF 10/11).
  lower_left: AcadRustPoint2d
  upper_right: AcadRustPoint2d
  // Camera (DXF 12/16/17/40/41/42/43/44/51).
  view_center: AcadRustPoint2d
  view_direction: AcadRustPoint3d
  view_target: AcadRustPoint3d
  view_height: number
  aspect_ratio: number
  lens_length: number
  view_twist: number
  front_clip: number
  back_clip: number
  // Snap / grid (DXF 13/14/15/50/61/72).
  snap_base: AcadRustPoint2d
  snap_spacing: AcadRustPoint2d
  grid_spacing: AcadRustPoint2d
  snap_rotation: number
  snap_isopair: number
  circle_zoom: number
  grid_major: number
  // UCS (DXF 110/111/112/79/146).
  ucs_origin: AcadRustPoint3d
  ucs_x_axis: AcadRustPoint3d
  ucs_y_axis: AcadRustPoint3d
  ucs_elevation: number
  ucs_ortho_type: number
  ucs_at_origin: boolean
  ucs_per_viewport: boolean
  ucsicon_lower: boolean
  ucsicon_origin: boolean
  ucsfollow: boolean
  // Display flags (carried only — not mapped; see the doc note above).
  fast_zoom: boolean
  grid_on: boolean
  snap_on: boolean
  snap_style: boolean
  render_mode: string
  perspective: boolean
  front_clipping: boolean
  back_clipping: boolean
  front_clip_at_eye: boolean
  use_default_lights: boolean
  default_lighting_type: number
  brightness: number
  contrast: number
  ambient_color: { Index: number } | null
  grid_flags: {
    beyond_limits: boolean
    adaptive: boolean
    subdivision: boolean
    follow_dynamic: boolean
  } | null
  // Cross-reference handles (unresolved; not mapped).
  xref_reference: boolean
  xref_resolved: boolean
  xref_dependent: boolean
  xref_handle: number
  background_handle: number
  visual_style_handle: number
  sun_handle: number
  named_ucs_handle: number
  base_ucs_handle: number
}

/** VPORT table (`Table<Vport>`, M4.7). */
export type AcadRustVportTable = AcadRustTable<AcadRustVport>

/**
 * One CLASSES-section / DWG class-table entry (`classes.json`, M4.8). Field names
 * mirror the acadrust serde; the first seven map onto the data-model `AcDbClass`
 * (DXF group codes 1/2/3/90/91/280/281), consumed by proxy-entity class-id
 * resolution and re-emitted by the DXF writer. `was_zombie` bridges to the
 * record's `wasProxy` (both are group 280). The trailing `class_number` /
 * `item_class_id` / `dwg_version` / `maintenance_version` / `unknown*` fields are
 * DWG-internal (no `AcDbClass` slot, not written to the DXF CLASSES section, so no
 * parity target) and are carried only.
 */
export interface AcadRustClass {
  dxf_name: string
  cpp_class_name: string
  application_name: string
  proxy_flags: number
  instance_count: number
  was_zombie: boolean
  is_an_entity: boolean
  class_number: number
  item_class_id: number
  dwg_version: number
  maintenance_version: number
  unknown1: number
  unknown2: number
}

/**
 * The `classes` section. Unlike the symbol tables (`AcadRustTable`), this arrives
 * as an ordered `entries` ARRAY (DWG class-table order — proxy entities index it
 * 0-based with class ids starting at 500) plus a `name_index` (name -> array slot);
 * there is no table handle.
 */
export interface AcadRustClassTable {
  entries: AcadRustClass[]
  name_index: Record<string, number>
}

/**
 * A single DXF result-buffer value carried by an XRECORD. acadrust emits each
 * value as a single-key enum. The primitives plus the four structured variants
 * (`Bool`, `Handle`, `Point3D`, `Chunk`) observed across the full sample corpus
 * are listed here; the scalar-only fixture (sample-drawing) exercises just the
 * first five, the wider set is what the W2 corpus sweep surfaced.
 */
export type AcadRustResultBufferValue =
  | { String: string }
  | { Int32: number }
  | { Int16: number }
  | { Byte: number }
  | { Double: number }
  | { Bool: boolean }
  | { Handle: number }
  | { Point3D: [number, number, number] }
  | { Chunk: number[] }

/** One `{ code, value }` pair in an XRECORD data list. */
export interface AcadRustXRecordEntry {
  code: number
  value: AcadRustResultBufferValue
}

/**
 * XRECORD object (`objects.json`). Self-contained application data: the entry
 * list is a result buffer. The object reaches the NOD through its parent
 * DICTIONARY (wired in M4.9b), so this slice only needs the handle + data.
 */
export interface AcadRustXRecord {
  handle: number
  owner: number
  name?: string
  cloning_flags?: string
  entries: AcadRustXRecordEntry[]
  object_references?: number[]
  entries_complete?: boolean
  reactors?: number[]
  xdictionary_handle?: number | null
}

/**
 * DICTIONARY object (`objects.json`, M4.9b). `entries` pairs each key with the
 * handle of the object it references, so the NOD graph is wired in a second
 * pass after the flat reads (mirroring the DXF reader). The duplicate_cloning
 * / hard_owner flags have no AcDbDictionary counterpart slot and stay unmapped
 * (the baseline carries them as defaults).
 */
export interface AcadRustDictionary {
  handle: number
  owner: number
  entries: [string, number][]
  duplicate_cloning: number
  hard_owner: boolean
  hard_owner_entries?: number[]
  reactors?: number[]
  xdictionary_handle?: number | null
}

/**
 * The LAYOUT object's plot-flag booleans, mirroring DXF group 70 bit semantics
 * (AcDbPlotSettings reads 70 as the same bit layout). `update_paper`,
 * `initializing`, `prev_plot_init` and `unknown_bits` have no DXF-side slot.
 */
export interface AcadRustPlotFlags {
  unknown_bits: number
  plot_viewport_borders: boolean
  show_plot_styles: boolean
  plot_centered: boolean
  plot_hidden: boolean
  use_standard_scale: boolean
  plot_plot_styles: boolean
  scale_lineweights: boolean
  print_lineweights: boolean
  draw_viewports_first: boolean
  model_type: boolean
  update_paper: boolean
  zoom_to_paper_on_update: boolean
  initializing: boolean
  prev_plot_init: boolean
}

/**
 * One LAYOUT object (AcDbLayout + embedded AcDbPlotSettings flattened by the
 * acadrust dumper into a single 51-field variant). Coordinates are plain
 * tuples; `block_record` references the BLOCK-RECORD table by DWG handle.
 */
export interface AcadRustLayout {
  handle: number
  owner: number
  name: string
  flags: number
  tab_order: number
  min_limits: [number, number]
  max_limits: [number, number]
  insertion_base: [number, number, number]
  min_extents: [number, number, number]
  max_extents: [number, number, number]
  elevation: number
  ucs_origin: [number, number, number]
  ucs_x_axis: [number, number, number]
  ucs_y_axis: [number, number, number]
  ucs_ortho_type: number
  block_record: number
  viewport: number
  viewports: number[]
  base_ucs: number
  named_ucs: number
  reactors?: number[]
  xdictionary_handle?: number | null
  paper_width: number
  paper_height: number
  plot_rotation: number
  plot_flags: AcadRustPlotFlags
  plot_page_name: string
  plot_printer_name: string
  paper_size: string
  plot_view_name: string
  plot_style_sheet: string
  plot_margin_left: number
  plot_margin_bottom: number
  plot_margin_right: number
  plot_margin_top: number
  plot_origin_x: number
  plot_origin_y: number
  plot_window_min_x: number
  plot_window_min_y: number
  plot_window_max_x: number
  plot_window_max_y: number
  plot_paper_units: number
  plot_type: number
  plot_scale_numerator: number
  plot_scale_denominator: number
  plot_scale_type: number
  plot_scale_factor: number
  paper_image_origin_x: number
  paper_image_origin_y: number
  shade_plot_mode: number
  shade_plot_resolution: number
  shade_plot_dpi: number
  plot_view_handle: number
  visual_style_handle: number
}

/** `acadrust` GROUP object (DWG OBJECTS `Group` variant). */
export interface AcadRustGroup {
  handle: number
  owner: number
  name: string
  unnamed: boolean
  description: string
  entities: number[]
  selectable: boolean
}

