/** A single OBJECTS-section entry; modeled variants are optional keys. */
export interface AcadRustObjectEntry {
  XRecord?: AcadRustXRecord
  Dictionary?: AcadRustDictionary
  Layout?: AcadRustLayout
  Group?: AcadRustGroup
  MLineStyle?: AcadRustMLineStyle
  MultiLeaderStyle?: AcadRustMultiLeaderStyle
}

/** The `objects.json` OBJECTS section: `handle -> object variant`. */
export type AcadRustObjects = Record<string, AcadRustObjectEntry>

/**
 * The `common` block every `EntityType` variant carries. Fully modeling every
 * entity geometry is a later milestone (M4.1+); the fields below are enough for
 * the Slice 0 page reader to attribute unknown/unmapped entities and for later
 * slices to extend incrementally.
 */
export interface AcadRustEntityCommon {
  handle: number
  layer: string
  color: AcadRustColor
  line_weight: AcadRustLineWeight
  linetype: string
  linetype_scale: number
  transparency: AcadRustTransparency
  color_name: string | null
  invisible: boolean
  extended_data: { records: unknown[] }
  reactors: unknown[]
  xdictionary_handle: number | null
  owner_handle: number | null
  full_visual_style_handle: number | null
}

/**
 * One externally-tagged `EntityType` page element: a single-key object whose key
 * is the variant name (`"Line"`, `"Dimension"` -> nested variant, ...). The
 * variant payload is narrowed by each entity mapper as that class reaches
 * Gate 2; the discriminant is read through {@link acadRustEntityKind}.
 */
export type AcadRustEntity = Record<string, unknown>

/**
 * The `Line` variant payload (`EntityType::Line`). Geometry is WCS; `normal` is
 * the extrusion/OCS direction (group 210), defaulting to `+Z`, and `thickness`
 * is group 39 — most 2D drawings carry `0` / `+Z`.
 */
export interface AcadRustLinePayload {
  common: AcadRustEntityCommon
  start: AcadRustPoint3d
  end: AcadRustPoint3d
  thickness: number
  normal: AcadRustPoint3d
}

/**
 * `EntityType::Circle` (`acadrust::entities::circle::Circle`). `center`/`normal`
 * are OCS (`normal` = extrusion direction, group 210; `+Z` for planar drawings),
 * `radius` group 40, `thickness` group 39.
 */
export interface AcadRustCirclePayload {
  common: AcadRustEntityCommon
  center: AcadRustPoint3d
  radius: number
  thickness: number
  normal: AcadRustPoint3d
}

/**
 * `EntityType::Arc`. Angles are radians measured in the OCS about `normal`,
 * counter-clockwise from start to end (DXF 50/51).
 */
export interface AcadRustArcPayload {
  common: AcadRustEntityCommon
  center: AcadRustPoint3d
  radius: number
  start_angle: number
  end_angle: number
  thickness: number
  normal: AcadRustPoint3d
}

/**
 * `EntityType::Ellipse`. `major_axis` is the major-axis endpoint relative to the
 * center (its length is the major radius, DXF 10/20/30); `minor_axis_ratio` is
 * minor/major (DXF 41); start/end are curve *parameters* (DXF 41... 21/22), not
 * angles — a full ellipse spans `[0, 2π]`.
 */
export interface AcadRustEllipsePayload {
  common: AcadRustEntityCommon
  center: AcadRustPoint3d
  major_axis: AcadRustPoint3d
  minor_axis_ratio: number
  start_parameter: number
  end_parameter: number
  normal: AcadRustPoint3d
}

/** One LWPOLYLINE vertex: a 2D OCS location plus per-segment bulge and widths. */
export interface AcadRustLwVertex {
  location: AcadRustPoint2d
  bulge: number
  start_width: number
  end_width: number
  vertex_id: number
}

/**
 * `EntityType::LwPolyline` (lightweight 2D polyline). Vertices carry bulge/width;
 * `constant_width` (DXF 43) applies when a vertex's own widths are zero; `elevation`
 * is the shared plane Z (group 30), `thickness` group 39, `normal` group 210.
 */
export interface AcadRustLwPolylinePayload {
  common: AcadRustEntityCommon
  vertices: AcadRustLwVertex[]
  is_closed: boolean
  plinegen: boolean
  constant_width: number
  elevation: number
  thickness: number
  normal: AcadRustPoint3d
}

/** Legacy `Polyline` vertex (always a 3D location + flag word). */
export interface AcadRustVertex3d {
  location: AcadRustPoint3d
  flags: { bits: number }
}

/**
 * `EntityType::Polyline` (legacy POLYLINE carrying 3D vertices). `flags.bits`
 * mirrors DXF group 70 (bit 1 closed, bit 8 3D, bit 4 spline-fit).
 */
export interface AcadRustPolylinePayload {
  common: AcadRustEntityCommon
  flags: { bits: number }
  vertices: AcadRustVertex3d[]
}

/** Heavy 2D polyline vertex (2D location in OCS + width/bulge/tangent). */
export interface AcadRustVertex2d {
  location: AcadRustPoint3d
  flags: { bits: number }
  start_width: number
  end_width: number
  bulge: number
  curve_tangent: number
  id: number
}

/**
 * `EntityType::Polyline2D` (legacy heavy 2D POLYLINE). `flags.bits` group 70;
 * per-vertex bulge/width override the polyline-level `start_width`/`end_width`.
 */
export interface AcadRustPolyline2DPayload {
  common: AcadRustEntityCommon
  flags: { bits: number }
  smooth_surface: unknown
  start_width: number
  end_width: number
  thickness: number
  elevation: number
  normal: AcadRustPoint3d
  vertices: AcadRustVertex2d[]
}

/** `EntityType::Polyline3D` vertex: a WCS `position` plus a raw flag word. */
export interface AcadRustPolyline3DVertex {
  handle: number
  layer: string
  position: AcadRustPoint3d
  flags: number
}

/** Named 3D-polyline flags (acadrust `Polyline3D`), unlike legacy `bits`. */
export interface AcadRustPolyline3DFlags {
  closed: boolean
  spline_fit: boolean
  is_3d: boolean
  is_3d_mesh: boolean
  mesh_closed_n: boolean
  is_polyface_mesh: boolean
  linetype_continuous: boolean
}

/**
 * `EntityType::Polyline3D` (3D POLYLINE / POLYMESH). Distinct serde shape from
 * the legacy {@link AcadRustPolylinePayload}: named boolean `flags` and vertices
 * keyed by `position`. `smooth_type` is always `"None"` in the corpus; spline
 * fitting is signalled by `flags.spline_fit`. Mesh counters
 * (`mesh_m_count`/`mesh_n_count`) and `smooth_*_density` are only meaningful for
 * 3D-mesh / polyface variants, which do not occur in the samples.
 */
export interface AcadRustPolyline3DPayload {
  common: AcadRustEntityCommon
  flags: AcadRustPolyline3DFlags
  smooth_type: string
  default_start_width: number
  default_end_width: number
  mesh_m_count: number
  mesh_n_count: number
  smooth_m_density: number
  smooth_n_density: number
  elevation: number
  normal: AcadRustPoint3d
  vertices: AcadRustPolyline3DVertex[]
}

/**
 * `EntityType::Point` (DXF POINT). `location` is the WCS position; `thickness`
 * group 39, `normal` the extrusion direction (group 210), and `x_axis_angle`
 * the UCS X-axis rotation recorded when the point was created (group 50,
 * radians; only meaningful when PDMODE is nonzero).
 */
export interface AcadRustPointPayload {
  common: AcadRustEntityCommon
  location: AcadRustPoint3d
  thickness: number
  normal: AcadRustPoint3d
  x_axis_angle: number
}

/**
 * `EntityType::Solid` (DXF SOLID / TRACE). Four corners map to DXF group
 * 10/11/12/13; the filled outline is drawn 1→2→4→3 (opposite-edge storage),
 * handled inside the data-model trace. `is_trace` selects the TRACE vs SOLID
 * subclass name but is `false` throughout the corpus.
 */
export interface AcadRustSolidPayload {
  common: AcadRustEntityCommon
  first_corner: AcadRustPoint3d
  second_corner: AcadRustPoint3d
  third_corner: AcadRustPoint3d
  fourth_corner: AcadRustPoint3d
  normal: AcadRustPoint3d
  thickness: number
  is_trace: boolean
}

/**
 * `EntityType::Leader` (DXF LEADER). A straight/spline leader line through
 * `vertices` with arrow/hookline flags and the owning dimension style. Corpus
 * leaders are always `StraightLine` + `NoAnnotation`.
 */
export interface AcadRustLeaderPayload {
  common: AcadRustEntityCommon
  vertices: AcadRustPoint3d[]
  path_type: string
  creation_type: string
  arrow_enabled: boolean
  hookline_enabled: boolean
  hookline_direction: string
  text_height: number
  text_width: number
  dimension_style: string
  normal: AcadRustPoint3d
}

/** One leader line inside a multi-leader root (points + per-line overrides). */
export interface AcadRustMLeaderLine {
  points: AcadRustPoint3d[]
  path_type?: string
  line_color?: AcadRustColor
  line_weight?: AcadRustLineWeight
  arrowhead_handle?: number | null
  arrowhead_size?: number
}

/** One leader root (a branch of the multi-leader) inside `context`. */
export interface AcadRustMLeaderLeaderRoot {
  leader_index?: number
  connection_point?: AcadRustPoint3d
  direction?: AcadRustPoint3d
  lines?: AcadRustMLeaderLine[]
  landing_distance?: number
  text_attachment_direction?: string
}

/** The `context` block of a multi-leader: leader roots + text content fields. */
export interface AcadRustMLeaderContext {
  leader_roots?: AcadRustMLeaderLeaderRoot[]
  scale_factor?: number
  text_height?: number
  text_color?: AcadRustColor
  text_normal?: AcadRustPoint3d
  has_text_contents?: boolean
  landing_gap?: number
  arrowhead_size?: number
}

/**
 * `EntityType::MultiLeader` (DXF MULTILEADER). Rich entity: leader geometry
 * lives in `context.leader_roots[].lines[].points`; content type, dogleg,
 * landing and colors are top-level scalars. Style/annotation references are
 * DWG handles bridged to object ids. Deep per-field override enums (text
 * attachment codes, block-attribute rows, the embedded MText object) are
 * carried here but not all mapped to the data-model (see converter).
 */
export interface AcadRustMultiLeaderPayload {
  common: AcadRustEntityCommon
  content_type: string
  path_type: string
  context?: AcadRustMLeaderContext
  line_color?: AcadRustColor
  line_weight?: AcadRustLineWeight
  line_type_handle?: number | null
  enable_landing?: boolean
  enable_dogleg?: boolean
  dogleg_length?: number
  arrowhead_handle?: number | null
  arrowhead_size?: number
  style_handle?: number | null
  text_style_handle?: number | null
  block_content_handle?: number | null
  scale_factor?: number
  property_override_flags?: string
  dwg_version?: number
}

/**
 * `EntityType::Ole2Frame` (DXF OLE2FRAME). A display frame hosting an embedded /
 * linked OLE 2 object. Only the frame rectangle
 * (`upper_left_corner`/`lower_right_corner`) and object type are recoverable from
 * the corpus; the `storage` compound-file binary is opaque and non-renderable, so
 * it is carried as `unknown` and skipped by the converter.
 */
export interface AcadRustOle2FramePayload {
  common: AcadRustEntityCommon
  version?: number
  source_application?: string
  upper_left_corner?: AcadRustPoint3d
  lower_right_corner?: AcadRustPoint3d
  ole_object_type?: string
  is_paper_space?: boolean
  lock_aspect?: number
  dwg_mode?: number
  envelope?: unknown
  storage?: unknown
}

/** One content entry inside a table cell (`contents[]`). */
export interface AcadRustTableCellContent {
  content_type?: string
  value?: {
    value_type?: string
    text?: string
    formatted_value?: string
    numeric_value?: number
  }
  text_height?: number
  alignment?: number
  rotation?: number
}

/** One table cell (`rows[].cells[]`). */
export interface AcadRustTableCellPayload {
  cell_type?: string
  contents?: AcadRustTableCellContent[]
  merge_width?: number
  merge_height?: number
  style?: unknown
}

/** One table row (`rows[]`). */
export interface AcadRustTableRow {
  height?: number
  cells?: AcadRustTableCellPayload[]
}

/** One table column (`columns[]`). */
export interface AcadRustTableColumn {
  name?: string
  width?: number
}

/**
 * `EntityType::Table` (DXF ACAD_TABLE). An n x m grid of cells whose contents
 * are primarily text. The converter rebuilds the row/column grid (heights +
 * widths + text cells) for renderable parity; deep table-style / break / field /
 * merged-cell / numeric-alignment override tables are deferred pending baseline
 * evidence.
 */
export interface AcadRustTablePayload {
  common: AcadRustEntityCommon
  name?: string
  block_name?: string
  rows?: AcadRustTableRow[]
  columns?: AcadRustTableColumn[]
  insertion_point?: AcadRustPoint3d
  normal?: AcadRustPoint3d
  horizontal_direction?: AcadRustPoint3d
  data_version?: number
  table_style_handle?: number | null
  base_style?: unknown
  merged_ranges?: unknown
  break_ranges?: unknown
  field_handles?: unknown
}

/** SPLINE flag word (`flags.closed` = DXF 70 bit 1, etc.). */
export interface AcadRustSplineFlags {
  closed: boolean
  periodic: boolean
  rational: boolean
  planar: boolean
  linear: boolean
}

/**
 * `EntityType::Spline` (NURBS). Control points are OCS; `weights` are meaningful
 * only when `flags.rational`. Fit points are an alternative representation used
 * when control/knot data is absent.
 */
export interface AcadRustSplinePayload {
  common: AcadRustEntityCommon
  degree: number
  flags: AcadRustSplineFlags
  knots: number[]
  control_points: AcadRustPoint3d[]
  weights: number[]
  fit_points: AcadRustPoint3d[]
  normal: AcadRustPoint3d
}

/**
 * One `BLOCK-RECORD` table entry (`acadrust::tables::BlockRecord`). The record
 * is the block *definition* container: `name` is the key an {@link AcadRustInsertPayload}'s `block_name` resolves against, `base_point` (WCS) is the insertion
 * origin, `entity_handles` bounds the block's own entity page range, and `flags`
 * are discrete booleans mirroring DXF group 70 (anonymous / has attributes /
 * xref / overlay / external / unloaded).
 */
export interface AcadRustBlockRecordFlags {
  anonymous: boolean
  has_attributes: boolean
  is_xref: boolean
  is_xref_overlay: boolean
  is_external: boolean
  is_xref_unloaded: boolean
}

export interface AcadRustBlockRecord {
  handle: number
  block_entity_handle: number
  block_end_handle: number
  name: string
  flags: AcadRustBlockRecordFlags
  layout: number
  units: number
  explodable: boolean
  scale_uniformly: boolean
  entity_handles: number[]
  xref_path: string
  description: string
  insert_handles: number[]
  base_point: AcadRustPoint3d
}

/** BLOCK-RECORD symbol table (`Table<BlockRecord>`). */
export type AcadRustBlockRecordTable = AcadRustTable<AcadRustBlockRecord>

/**
 * Attribute flag bits, serialized by acadrust as a plain object of booleans
 * (`AttributeFlags`), not a DXF bit mask — the `from_bits`/`to_bits` helpers on
 * the Rust side are conveniences never crossing the wire.
 */
export interface AcadRustAttributeFlags {
  invisible: boolean
  constant: boolean
  verify: boolean
  preset: boolean
  locked_position: boolean
  annotative: boolean
}

/**
 * Multiline attribute kind (`MTextFlag`). acadrust emits the PascalCase variant
 * name; the `= 0/2/4` Rust discriminants are repr hints serde ignores.
 */
export type AcadRustAttributeMTextFlag = 'SingleLine' | 'MultiLine' | 'ConstantMultiLine'

/**
 * One ATTRIB carried by an {@link AcadRustInsertPayload}
 * (`acadrust::entities::attribute_entity::AttributeEntity`). Text-display
 * fields mirror {@link AcadRustTextPayload} but use the Rust field names
 * (`text_style`/`text_generation_flags`); `alignment_point` is always present
 * (a `Vector3`, non-nullable on the wire). `embedded_mtext` carries the full
 * R2018+ multiline MTEXT layout when `is_multiline`/`mtext_flag` mark it so.
 */
export interface AcadRustAttribute {
  common: AcadRustEntityCommon
  tag: string
  value: string
  insertion_point: AcadRustPoint3d
  alignment_point: AcadRustPoint3d
  height: number
  rotation: number
  width_factor: number
  oblique_angle: number
  text_style: string
  text_generation_flags: number
  horizontal_alignment: AcadRustTextHorizontalAlignment
  vertical_alignment: AcadRustTextVerticalAlignment
  flags: AcadRustAttributeFlags
  field_length: number
  normal: AcadRustPoint3d
  mtext_flag: AcadRustAttributeMTextFlag
  is_multiline: boolean
  line_count: number
  embedded_mtext: AcadRustMTextPayload | null
  attdef_handle: number
  lock_position: boolean
}

/**
 * `EntityType::AttributeDefinition` (DXF ATTDEF, block-definition attribute
 * template). Structurally identical to {@link AcadRustAttribute} except it
 * carries `prompt` + `default_value` (the template text) instead of a concrete
 * `value`, and no owning `attdef_handle`. Maps to `AcDbAttributeDefinition`
 * (which extends `AcDbText` like `AcDbAttribute`).
 */
export interface AcadRustAttributeDefinitionPayload {
  common: AcadRustEntityCommon
  tag: string
  prompt: string
  default_value: string
  insertion_point: AcadRustPoint3d
  alignment_point: AcadRustPoint3d
  height: number
  rotation: number
  width_factor: number
  oblique_angle: number
  text_style: string
  text_generation_flags: number
  horizontal_alignment: AcadRustTextHorizontalAlignment
  vertical_alignment: AcadRustTextVerticalAlignment
  flags: AcadRustAttributeFlags
  field_length: number
  normal: AcadRustPoint3d
  mtext_flag: AcadRustAttributeMTextFlag
  is_multiline: boolean
  line_count: number
  embedded_mtext: AcadRustMTextPayload | null
  lock_position: boolean
}

/** One per-style-element parameter block of an MLINE vertex segment. */
export interface AcadRustMLineVertexSegment {
  parameters?: number[]
  area_fill_parameters?: number[]
}

/** One MLINE vertex (`vertices[]`) with its path frame and element segments. */
export interface AcadRustMLineVertex {
  position: AcadRustPoint3d
  direction: AcadRustPoint3d
  miter: AcadRustPoint3d
  segments?: AcadRustMLineVertexSegment[]
}

/**
 * `EntityType::MLine` (DXF MLINE). A multiline along a reference path with one
 * element offset per `MLINESTYLE` line. `justification` is the DXF name
 * (`Top`/`Zero`/`Bottom`), `start_point` the path start, `vertices` the per-
 * vertex frame (`position`/`direction`/`miter`) plus per-element `parameters`.
 * The `flags` string enum has no baseline group-70 backing and is deferred.
 */
export interface AcadRustMLinePayload {
  common: AcadRustEntityCommon
  flags?: string
  justification?: string
  normal?: AcadRustPoint3d
  scale_factor?: number
  start_point?: AcadRustPoint3d
  style_handle?: number
  style_name?: string
  style_element_count?: number
  vertices?: AcadRustMLineVertex[]
}

/**
 * `EntityType::Insert` (block reference). `block_name` resolves against the
 * BLOCK-RECORD table; `insert_point` is WCS, `x/y/z_scale` and `rotation`
 * (radians) are the OCS placement transform, `normal` the extrusion direction
 * (group 210). `column_count`/`row_count`/`column_spacing`/`row_spacing` carry
 * the MINSERT array (both 1 for a plain INSERT); `attributes` are the concrete
 * ATTRIB values overriding the block's attribute definitions.
 */
export interface AcadRustInsertPayload {
  common: AcadRustEntityCommon
  block_name: string
  insert_point: AcadRustPoint3d
  x_scale: number
  y_scale: number
  z_scale: number
  rotation: number
  normal: AcadRustPoint3d
  column_count: number
  row_count: number
  column_spacing: number
  row_spacing: number
  attributes: AcadRustAttribute[]
}

/**
 * Text alignment / attachment / flow enums. acadrust serializes each as a bare
 * PascalCase variant string (unit variants under the default externally-tagged
 * representation), and the numeric discriminants (`= 1`.. on `AttachmentPoint`
 * etc.) are Rust `repr` hints serde ignores — the wire form is the name.
 */
export type AcadRustTextHorizontalAlignment =
  | 'Left'
  | 'Center'
  | 'Right'
  | 'Aligned'
  | 'Middle'
  | 'Fit'
export type AcadRustTextVerticalAlignment = 'Baseline' | 'Bottom' | 'Middle' | 'Top'
export type AcadRustAttachmentPoint =
  | 'TopLeft'
  | 'TopCenter'
  | 'TopRight'
  | 'MiddleLeft'
  | 'MiddleCenter'
  | 'MiddleRight'
  | 'BottomLeft'
  | 'BottomCenter'
  | 'BottomRight'
export type AcadRustDrawingDirection = 'LeftToRight' | 'TopToBottom' | 'ByStyle'
export type AcadRustLineSpacingStyle = 'AtLeast' | 'Exactly'

/**
 * `EntityType::Text` (single-line TEXT, `acadrust::entities::text::Text`).
 * `insertion_point` (DXF 10) is OCS and `alignment_point` (DXF 11, null when the
 * file omits it) is the placement anchor for non-default alignments; `rotation`
 * / `oblique_angle` are radians; `horizontal_alignment` / `vertical_alignment`
 * are the two orthogonal axes (DXF 72/73); `generation_flags` (DXF 71) bit 2 =
 * backward, bit 4 = upside-down; `thickness` group 39, `normal` group 210.
 */
export interface AcadRustTextPayload {
  common: AcadRustEntityCommon
  value: string
  insertion_point: AcadRustPoint3d
  alignment_point: AcadRustPoint3d | null
  height: number
  rotation: number
  width_factor: number
  oblique_angle: number
  style: string
  horizontal_alignment: AcadRustTextHorizontalAlignment
  vertical_alignment: AcadRustTextVerticalAlignment
  normal: AcadRustPoint3d
  thickness: number
  generation_flags: number
}

/**
 * `EntityType::MText` (multiline MTEXT, `acadrust::entities::mtext::MText`).
 * `insertion_point` is the attachment anchor (OCS); `rectangle_width` (DXF 41)
 * is the word-wrap width and `rectangle_height` (DXF 42/43, null when unset) the
 * reference box height; `attachment_point` (DXF 71) and `drawing_direction`
 * (DXF 72) are the enums above; `line_spacing_factor` group 44,
 * `line_spacing_style` group 73; `background_fill_flags` group 90 (bit 0x01 =
 * fill on); `extents_width`/`extents_height` are output-only layout extents.
 * Column data / background color are not yet mapped this milestone.
 */
export interface AcadRustMTextPayload {
  common: AcadRustEntityCommon
  value: string
  insertion_point: AcadRustPoint3d
  height: number
  rectangle_width: number
  rectangle_height: number | null
  rotation: number
  /**
   * WCS reading (baseline) direction acadrust derives for DWG MTEXT — the text
   * X-axis, equal to `(cos rotation, sin rotation, 0)` for planar text and the
   * fully extrusion-transformed vector for tilted text. Present on the DWG wire,
   * absent/null for DXF-sourced MTEXT (where the converter falls back to
   * `rotation`). The data-model MTEXT renderer lets a non-zero `direction`
   * override `rotation`, so this must be carried across or rotated MTEXT
   * collapses back to horizontal.
   */
  dwg_x_direction?: AcadRustPoint3d | null
  style: string
  attachment_point: AcadRustAttachmentPoint
  drawing_direction: AcadRustDrawingDirection
  line_spacing_factor: number
  line_spacing_style: AcadRustLineSpacingStyle
  normal: AcadRustPoint3d
  background_fill_flags: number
  background_scale: number
  is_annotative: boolean
  extents_width: number
  extents_height: number
}

/**
 * Dimension / hatch serde enums.
 *
 * `DimensionType`, `HatchPatternType`, `HatchStyleType` and the dimension
 * attachment point are unit-variant enums acadrust serializes as bare PascalCase
 * variant names (the Rust `= n` discriminants are repr hints serde ignores), so
 * the wire form is the string — the same convention as the text enums above.
 *
 * NOTE `DimensionBase.line_spacing_style` is a plain `i16` (DXF 73: 1 = at least,
 * 2 = exact), NOT one of those enums — it arrives as a number.
 */
export type AcadRustDimensionType =
  | 'Linear'
  | 'Aligned'
  | 'Angular'
  | 'Diameter'
  | 'Radius'
  | 'Angular3Point'
  | 'Ordinate'
  | 'ArcLength'
  | 'LargeRadial'
export type AcadRustHatchPatternType = 'UserDefined' | 'Predefined' | 'Custom'
export type AcadRustHatchStyleType = 'Normal' | 'Outer' | 'Ignore'

/**
 * `DimensionBase` — the shared fields every `Dimension` sub-variant nests under
 * its `base` key. `definition_point` (DXF 10) and `text_middle_point` (DXF 11)
 * are WCS; `insertion_point` (DXF 12) is the clone/relative block position; the
 * low bits of the DXF group-70 kind are carried by `dimension_type` and the
 * user-positioned text flag by `text_user_positioned`; `block_name` is the
 * anonymous `*D…` dimension block that holds the rendered geometry (created and
 * paged by the M4.2 block layer). `attachment_point` reuses the text attachment
 * enum (identical `TopLeft`..`BottomRight` variant set).
 */
export interface AcadRustDimensionBase {
  common: AcadRustEntityCommon
  definition_point: AcadRustPoint3d
  text_middle_point: AcadRustPoint3d
  insertion_point: AcadRustPoint3d
  dimension_type: AcadRustDimensionType
  attachment_point: AcadRustAttachmentPoint
  text: string
  user_text: string | null
  normal: AcadRustPoint3d
  text_rotation: number
  horizontal_direction: number
  style_name: string
  actual_measurement: number
  version: number
  block_name: string
  line_spacing_factor: number
  line_spacing_style: number
  insertion_scale: AcadRustPoint3d
  insertion_rotation: number
  dwg_unknown_bit: boolean
  flip_arrow1: boolean
  flip_arrow2: boolean
  dwg_flags_byte: number
  text_user_positioned: boolean
}

export interface AcadRustDimensionLinearPayload {
  base: AcadRustDimensionBase
  first_point: AcadRustPoint3d
  second_point: AcadRustPoint3d
  definition_point: AcadRustPoint3d
  rotation: number
  ext_line_rotation: number
}

export interface AcadRustDimensionAlignedPayload {
  base: AcadRustDimensionBase
  first_point: AcadRustPoint3d
  second_point: AcadRustPoint3d
  definition_point: AcadRustPoint3d
  ext_line_rotation: number
}

export interface AcadRustDimensionRadiusPayload {
  base: AcadRustDimensionBase
  definition_point: AcadRustPoint3d
  angle_vertex: AcadRustPoint3d
  leader_length: number
}

export interface AcadRustDimensionDiameterPayload {
  base: AcadRustDimensionBase
  definition_point: AcadRustPoint3d
  angle_vertex: AcadRustPoint3d
  leader_length: number
}

export interface AcadRustDimensionAngularPayload {
  base: AcadRustDimensionBase
  dimension_arc?: AcadRustPoint3d
  first_point: AcadRustPoint3d
  second_point: AcadRustPoint3d
  angle_vertex: AcadRustPoint3d
  definition_point: AcadRustPoint3d
}

export interface AcadRustDimensionOrdinatePayload {
  base: AcadRustDimensionBase
  definition_point: AcadRustPoint3d
  feature_location: AcadRustPoint3d
  leader_endpoint: AcadRustPoint3d
  is_ordinate_type_x: boolean
}

export interface AcadRustDimensionArcPayload {
  base: AcadRustDimensionBase
  definition_point: AcadRustPoint3d
  first_extension_point: AcadRustPoint3d
  second_extension_point: AcadRustPoint3d
  center_point: AcadRustPoint3d
  is_partial: boolean
  arc_start_parameter: number
  arc_end_parameter: number
  has_leader: boolean
  first_leader_point: AcadRustPoint3d
  second_leader_point: AcadRustPoint3d
}

/**
 * `EntityType::Dimension` — an externally-tagged enum whose single key selects
 * the sub-variant (`"Linear"`, `"Aligned"`, …) and whose value nests the
 * sub-struct. LargeRadial has no clean data-model counterpart and stays
 * unknown-counted, so it is typed loosely.
 */
export interface AcadRustDimensionVariants {
  Linear?: AcadRustDimensionLinearPayload
  Aligned?: AcadRustDimensionAlignedPayload
  Radius?: AcadRustDimensionRadiusPayload
  Diameter?: AcadRustDimensionDiameterPayload
  Angular2Ln?: AcadRustDimensionAngularPayload
  Angular3Pt?: AcadRustDimensionAngularPayload
  Ordinate?: AcadRustDimensionOrdinatePayload
  Arc?: AcadRustDimensionArcPayload
  LargeRadial?: unknown
}

/** HATCH boundary-path flag word (`bits` mirrors DXF group 71 of the path). */
export interface AcadRustHatchBoundaryPathFlags {
  bits: number
}

/** Boundary edge payloads (all coordinates are OCS 2D except spline weights). */
export interface AcadRustHatchLineEdge {
  start: AcadRustPoint2d
  end: AcadRustPoint2d
}
export interface AcadRustHatchCircularArcEdge {
  center: AcadRustPoint2d
  radius: number
  start_angle: number
  end_angle: number
  counter_clockwise: boolean
}
export interface AcadRustHatchEllipticArcEdge {
  center: AcadRustPoint2d
  major_axis_endpoint: AcadRustPoint2d
  minor_axis_ratio: number
  start_angle: number
  end_angle: number
  counter_clockwise: boolean
}
export interface AcadRustHatchSplineEdge {
  degree: number
  rational: boolean
  periodic: boolean
  knots: number[]
  /** Control points where `z` carries the NURBS weight (per acadrust docs). */
  control_points: AcadRustPoint3d[]
  fit_points: AcadRustPoint2d[]
  start_tangent: AcadRustPoint2d
  end_tangent: AcadRustPoint2d
}
export interface AcadRustHatchPolylineEdge {
  /** Vertices where `z` carries the segment bulge. */
  vertices: AcadRustPoint3d[]
  is_closed: boolean
}

/**
 * One `BoundaryEdge` — externally tagged, single-key (`{"Line":{…}}`,
 * `{"CircularArc":{…}}`, …), the same convention as {@link AcadRustEntity}.
 */
export type AcadRustHatchBoundaryEdge =
  | { Line: AcadRustHatchLineEdge }
  | { CircularArc: AcadRustHatchCircularArcEdge }
  | { EllipticArc: AcadRustHatchEllipticArcEdge }
  | { Spline: AcadRustHatchSplineEdge }
  | { Polyline: AcadRustHatchPolylineEdge }

export interface AcadRustHatchBoundaryPath {
  flags: AcadRustHatchBoundaryPathFlags
  edges: AcadRustHatchBoundaryEdge[]
  boundary_handles: number[]
}

export interface AcadRustHatchPatternLine {
  angle: number
  base_point: AcadRustPoint2d
  offset: AcadRustPoint2d
  dash_lengths: number[]
}

export interface AcadRustHatchPattern {
  name: string
  description: string
  lines: AcadRustHatchPatternLine[]
}

/**
 * `EntityType::Hatch` (and the AcDbMPolygon class variant, distinguished by
 * `is_mpolygon`). Boundary geometry lives in `paths`; `pattern_type` / `style`
 * are the PascalCase enums above; the MPolygon-only extras and the gradient
 * block stay unmapped this milestone.
 */
export interface AcadRustHatchPayload {
  common: AcadRustEntityCommon
  is_mpolygon: boolean
  elevation: number
  normal: AcadRustPoint3d
  pattern: AcadRustHatchPattern
  is_solid: boolean
  is_associative: boolean
  pattern_type: AcadRustHatchPatternType
  pattern_angle: number
  pattern_scale: number
  is_double: boolean
  style: AcadRustHatchStyleType
  paths: AcadRustHatchBoundaryPath[]
  seed_points: AcadRustPoint2d[]
  pixel_size: number
}

/**
 * Return the single externally-tagged discriminant of an entity page element
 * (e.g. `"Line"`), or `undefined` if the object is not exactly one key. Keeps
 * the mappers from re-implementing the "outer-tagged enum" unwrap.
 */
export function acadRustEntityKind(entity: AcadRustEntity): string | undefined {
  const keys = Object.keys(entity)
  return keys.length === 1 ? keys[0] : undefined
}
